mapper.select:
SELECT l.id AS log_id, l.operate_type AS event_type, l.create_time AS event_time, l.order_id, o.order_no, o.goods_id, o.goods_name, o.goods_sn, o.goods_thumb, o.session_id, o.session_name, CASE WHEN l.operate_type = 3 AND split.n = 1 THEN COALESCE(l.prev_buyer_id, o.buyer_id) ELSE COALESCE(l.buyer_id, o.buyer_id) END AS buyer_id, CASE WHEN l.operate_type = 3 AND split.n = 1 THEN COALESCE(l.prev_buyer_name, o.buyer_name) ELSE COALESCE(l.buyer_name, o.buyer_name) END AS buyer_name, CASE WHEN l.operate_type = 3 AND split.n = 1 THEN COALESCE(l.prev_buyer_phone, o.buyer_phone) ELSE COALESCE(l.buyer_phone, o.buyer_phone) END AS buyer_phone, CASE WHEN l.operate_type = 3 AND split.n = 1 THEN -o.quantity WHEN l.operate_type = 3 AND split.n = 2 THEN o.quantity ELSE o.quantity END AS flow_quantity, o.unit_price, CASE WHEN l.operate_type = 2 THEN -o.total_amount WHEN l.operate_type = 3 AND split.n = 1 THEN -o.total_amount WHEN l.operate_type = 3 AND split.n = 2 THEN o.total_amount ELSE o.total_amount END AS signed_total_amount, CASE WHEN l.operate_type = 2 THEN -l.receipt_amount WHEN l.operate_type = 3 AND split.n = 1 THEN -l.receipt_amount WHEN l.operate_type = 3 AND split.n = 2 THEN l.receipt_amount ELSE l.receipt_amount END AS signed_receipt_amount, CASE WHEN l.operate_type = 2 THEN -l.payment_amount WHEN l.operate_type = 3 AND split.n = 1 THEN -l.payment_amount WHEN l.operate_type = 3 AND split.n = 2 THEN l.payment_amount ELSE l.payment_amount END AS signed_payment_amount, l.operate_user_id AS operator_id, l.operate_user_name AS operator_name, l.remark FROM t_rob_order_operate_log l INNER JOIN t_rob_order o ON o.id = l.order_id AND o.is_deleted = 0 LEFT JOIN (SELECT 1 AS n UNION ALL SELECT 2 AS n) split ON l.operate_type = 3 WHERE 1 = 1 AND l.order_id IN
#{oid}
ORDER BY l.create_time ASC, l.id ASC, split.n ASC
